/**
 * Native push notifications + deep linking.
 *
 * Wires APNs/FCM via @capacitor/push-notifications. On the web this is
 * a no-op — we already have web push via /sw-push.js.
 *
 * Flow:
 *   1. App boots → useNativePushSetup() runs once.
 *   2. We DO NOT request permission yet (Apple frowns on cold prompts).
 *   3. Call requestPushPermission() from a clear UX moment (e.g. after the
 *      first job is posted) and pre-flight with usePermissionRationale.
 *   4. On grant, the device token is saved to push_tokens.
 *   5. Tapping a push notification opens the app and routes to the link
 *      embedded in the notification's data payload.
 */
import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { isNativePlatform } from "@/lib/nativeInit";
import { supabase } from "@/integrations/supabase/client";
import { track, AhaEvent } from "@/lib/analytics";
import { report } from "@/lib/errorLogger";
import { usePermissionRationale } from "@/hooks/usePermissionRationale";
import {
  isPushSupported,
  registerServiceWorker,
  requestPushPermission as requestWebPushPermission,
  setNativePushPermission,
} from "@/lib/pushNotifications";
import { Browser } from "@capacitor/browser";
import { normalizeDeepLinkUrl, NATIVE_RETURN_SCHEME } from "@/lib/deepLinkRoute";
import { claimDeepLinkLaunch } from "@/lib/nativeLaunchMutex";
import { captureJobRef } from "@/lib/jobLinkRef";
import { rememberPendingSave } from "@/lib/jobIntent";

/**
 * The job id a notification is about, or null.
 *
 * Reads the three shapes the product actually emits, in precedence order:
 * `?quickApply=<id>` (the most common notification link there is — see
 * QuickApplyHandler.tsx:31), `?job=<id>` (the guest browse walls), and the
 * `/jobs/<id>` detail route. Anything else — `/messages`, `/earnings`,
 * `/admin` — has no job and returns null, which every caller treats as
 * "fall back to plain navigation".
 */
function jobIdFromLink(link: string): string | null {
  // A relative link needs a base to parse; the origin is thrown away.
  let url: URL;
  try {
    url = new URL(link, "https://app.invalid");
  } catch {
    return null;
  }
  const param = url.searchParams.get("quickApply") || url.searchParams.get("job");
  if (param) return param;
  const match = url.pathname.match(/^\/jobs\/([^/]+)$/);
  return match ? match[1] : null;
}

let listenersAttached = false;

// Pending token captured before supabase.auth has restored the session
// from local storage. APNs sometimes delivers the device token in
// <100ms of register() — faster than supabase-js's session hydration —
// so getUser() returns null and we'd lose the token. Buffer it here
// and flush on the next SIGNED_IN auth event.
let pendingToken: { token: string; platform: "ios" | "android" } | null = null;
let authListenerAttached = false;

// The token APNs/FCM handed THIS device in this app session — remembered so
// sign-out can delete just this device's row instead of nuking the user's
// tokens on every other device they're signed in on.
let currentDeviceToken: string | null = null;

/**
 * Translate Capacitor's `PermissionState` ("granted" | "denied" | "prompt" |
 * "prompt-with-rationale") into the web vocabulary `getPushPermission()`
 * speaks, and cache it there.
 *
 * `getPushPermission()` has to stay synchronous (NotificationPanel calls it
 * from a `useEffect` and from a realtime handler) but the native permission
 * check is async, so the native answer is pushed to it from here instead of
 * pulled.
 */
function publishNativePermission(receive: string): void {
  if (receive === "granted") setNativePushPermission("granted");
  else if (receive === "denied") setNativePushPermission("denied");
  else setNativePushPermission("default"); // "prompt" | "prompt-with-rationale"
}

// App version is exposed on `window.HELPR_BUILD` from main.tsx (set at
// bundle time). This avoids the previous hardcoded "1.0.4" which would
// silently lie after every iOS rebuild. Falls back to "unknown" if the
// global is missing (e.g. in SSR or pre-hydration test contexts).
function currentAppVersion(): string {
  if (typeof window === "undefined") return "unknown";
  return (window as { HELPR_BUILD?: string }).HELPR_BUILD ?? "unknown";
}

async function persistPushToken(userId: string, token: string, platform: "ios" | "android") {
  try {
    const { error } = await supabase.from("push_tokens").upsert(
      {
        user_id: userId,
        token,
        platform,
        device_id: platform + "-" + token.slice(0, 8),
        app_version: currentAppVersion(),
      },
      { onConflict: "user_id,token" },
    );
    if (error) {
      report(error, { tags: { source: "persistPushToken.upsert" }, context: { userId } });
    }
  } catch (err) {
    report(err, { tags: { source: "persistPushToken" }, context: { userId } });
  }
}

function attachAuthListenerOnce() {
  if (authListenerAttached) return;
  authListenerAttached = true;
  supabase.auth.onAuthStateChange((event, session) => {
    if ((event === "SIGNED_IN" || event === "INITIAL_SESSION" || event === "TOKEN_REFRESHED") && session?.user && pendingToken) {
      const { token, platform } = pendingToken;
      pendingToken = null;
      void persistPushToken(session.user.id, token, platform);
    }
  });
}

async function savePushToken(token: string, platform: "ios" | "android") {
  currentDeviceToken = token;
  try {
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await persistPushToken(user.id, token, platform);
      return;
    }
    // Session not yet restored — buffer the token and flush on first auth event.
    pendingToken = { token, platform };
    attachAuthListenerOnce();
  } catch (err) {
    report(err, { tags: { source: "savePushToken" } });
  }
}

/**
 * Append a `?ref=<token>` param to an internal path (e.g. "/dashboard?job=abc").
 * Preserves any existing query params; does NOT override an existing `ref` so
 * a notification that itself carries a ref (e.g. a shared link forwarded via
 * push) keeps the more-specific attribution.
 */
function appendRef(path: string, ref: string): string {
  try {
    // Use a dummy base so URL can parse relative paths.
    const url = new URL(path, "https://x");
    if (!url.searchParams.has("ref")) {
      url.searchParams.set("ref", ref);
    }
    // Return just path+search (strip the dummy base).
    return url.pathname + (url.search || "");
  } catch {
    // Malformed path — return as-is rather than breaking navigation.
    return path;
  }
}

/**
 * Mount once at the app root. Sets up listeners but does NOT request
 * permission. Call requestPushPermission() from a UX-appropriate moment.
 */
export function useNativePushSetup() {
  const navigate = useNavigate();

  useEffect(() => {
    if (!isNativePlatform || listenersAttached) return;
    listenersAttached = true;

    let cancelled = false;
    (async () => {
      try {
        const { PushNotifications } = await import("@capacitor/push-notifications");

        // Token registration succeeded.
        await PushNotifications.addListener("registration", async (token) => {
          // Defensive narrow: getPlatform can technically return 'web',
          // but registration fires only on native — anything other than
          // 'android' falls back to 'ios' (the dominant platform) so we
          // never write platform='web' into push_tokens (which has no
          // sender backend wired).
          const raw = (window as { Capacitor?: { getPlatform?: () => string } }).Capacitor?.getPlatform?.();
          const platform: "ios" | "android" = raw === "android" ? "android" : "ios";
          await savePushToken(token.value, platform);
        });

        // Token registration failed.
        await PushNotifications.addListener("registrationError", (err) => {
          report(err, { tags: { source: "push.registrationError" } });
        });

        // Foreground notification received. iOS suppresses the system banner
        // while the app is in the foreground, so surface an in-app toast —
        // otherwise an actively-browsing user gets no signal on a new
        // message / job match. Tapping routes to the link in the payload.
        await PushNotifications.addListener("pushNotificationReceived", async (notification) => {
          track(AhaEvent.PushReceivedForeground, {
            title: notification.title,
            data: notification.data,
          });
          const link = notification.data?.link;
          const hasInternalLink = typeof link === "string" && link.startsWith("/");
          // Append ?ref=notif so we can attribute sessions that open a job
          // from a foreground-toast "View" tap (same attribution path as a
          // background-tap open). captureJobRef validates the token before
          // persisting — "notif" is always valid.
          const linkWithRef = hasInternalLink
            ? appendRef(link as string, "notif")
            : link;
          const { toast } = await import("sonner");
          toast(notification.title || "New notification", {
            description: notification.body || undefined,
            action: hasInternalLink
              ? { label: "View", onClick: () => navigate(linkWithRef as string) }
              : undefined,
          });
        });

        // User tapped a notification while app was in background/closed.
        await PushNotifications.addListener("pushNotificationActionPerformed", (action) => {
          track(AhaEvent.AppOpenedFromPush, { action: action.actionId });
          const link = action.notification?.data?.link;
          // `actionId` is "tap" for the notification body, "dismiss" for a
          // swipe-away, or one of the identifiers AppDelegate.swift registers
          // on the JOB_APPLY / MESSAGE / JOB_ACCEPTED categories. Those
          // buttons only started existing when that registration landed — iOS
          // had been dropping every unregistered category silently — so every
          // branch below is reachable only on a build that carries it. An
          // unknown id falls through to plain navigation, which is what a
          // server-side category added ahead of an app release should do.
          const actionId = action.actionId;
          if (actionId === "dismiss") return;
          if (typeof link === "string" && link.startsWith("/")) {
            // Tag the navigation with ?ref=notif so the receiving page can
            // capture the attribution source via useJobRef().
            captureJobRef("notif");
            // CLAIM THE LAUNCH FIRST. A tap on a push notification while the
            // app is CLOSED is a cold launch: the app boots at "/",
            // NativeLaunchRouter resolves the default post-auth route async,
            // and — unless somebody claimed the launch — navigates there with
            // `replace: true`, throwing this link away. That is precisely the
            // race nativeLaunchMutex exists for, and the Universal-Link path
            // below already claims it (see handleIncomingUrl); the push-tap
            // path was the one participant that never did, so a tap from a
            // closed app landed on the default screen rather than on the thing
            // the notification was about.
            //
            // Claiming when the app was merely BACKGROUNDED is harmless:
            // NativeLaunchRouter only ever acts once, on its own mount, and
            // only when the initial path is "/".
            claimDeepLinkLaunch();

            const jobId = jobIdFromLink(link);

            // "Save" — the bookmark, not the application. Reuses the guest
            // save hook rather than writing here: rememberPendingSave stashes
            // the id in a tracked key and usePendingSaveConsumer upserts it
            // and toasts "Job saved" on the next Dashboard or JobDetail mount.
            // That matters because this handler can run during a COLD launch,
            // before a session exists — a write issued here would race
            // supabase-js's session hydration and fail as an anonymous
            // insert, which is the same class of loss the pending-token
            // buffer above exists to prevent. The consumer is gated on a real
            // user id, so the save lands once the session does. Navigating to
            // the job detail route both shows what was saved and guarantees a
            // consumer is mounted; without an id there is nothing to save, so
            // fall through to the link.
            if (actionId === "SAVE" && jobId) {
              rememberPendingSave(jobId);
              navigate(appendRef(`/jobs/${jobId}`, "notif"));
              return;
            }

            // "Apply" — open the apply sheet directly rather than dropping the
            // user on a feed to find the job again. `?quickApply=` is the
            // established param (jobIntent.postAuthDestination builds the same
            // URL for a guest returning from signup).
            if (actionId === "APPLY" && jobId) {
              navigate(appendRef(`/dashboard?quickApply=${encodeURIComponent(jobId)}`, "notif"));
              return;
            }

            // "Reply" (MESSAGE) and "Message" (JOB_ACCEPTED) both mean: take
            // me to the conversation. When the notification is already a
            // message push its own link is the thread, so prefer it and only
            // fall back to the inbox.
            if (actionId === "REPLY" || actionId === "OPEN_THREAD") {
              const dest = link.startsWith("/messages") ? link : "/messages";
              navigate(appendRef(dest, "notif"));
              return;
            }

            // "View", "tap", and anything unrecognised.
            navigate(appendRef(link, "notif"));
          }
        });

        if (cancelled) return;

        // Auto-register on every app boot when permission is already
        // granted. Capacitor's PushNotifications plugin does NOT cache or
        // re-emit the token across app launches — register() must be
        // called each session for the registration event to fire. Without
        // this, users who granted permission previously never get their
        // token persisted (the user-initiated requestPushPermission flow
        // is the only other call site, and it's gated behind a 30-day
        // snooze on the dashboard prompt). Idempotent + fast when already
        // registered.
        try {
          const status = await PushNotifications.checkPermissions();
          // Publish the native state to the synchronous accessor in
          // pushNotifications.ts. `getPushPermission()` cannot await
          // Capacitor, and NotificationPanel calls it inside a useEffect —
          // without this prime it would report "default" forever on native
          // and keep offering "Turn on notifications" to users who already
          // granted it.
          publishNativePermission(status.receive);
          if (status.receive === "granted") {
            await PushNotifications.register();
          }
        } catch (regErr) {
          report(regErr, { tags: { source: "push.autoRegister" } });
        }

        if (cancelled) return;

        // Universal Links / App Links — handle taps from outside the app.
        //
        // Host whitelist + short-link normalization live in
        // `@/lib/deepLinkRoute` so the routing table is unit-tested
        // independently of Capacitor's bridge, and so the AASA path
        // claims in public/.well-known/apple-app-site-association and
        // the JS routing stay in sync (both files reference the same
        // set of paths: /jobs/*, /j/*, /user/*, /u/*, /messages/*,
        // /m/*, /legal*, /post-job*).
        //
        // STRICT host check: on TestFlight cold-install, Capacitor
        // sometimes fires appUrlOpen with the install-source URL on
        // initial launch — without the whitelist a stale `/login` or
        // `/whatever` path would yank fresh-install users away from
        // the guest dashboard they were just rendered onto.
        const { App } = await import("@capacitor/app");

        const handleIncomingUrl = async (rawUrl: string) => {
          try {
            // Parse for analytics (host + raw path) even if we end up
            // ignoring the URL — we still want to know how often
            // foreign-host links reach the bridge.
            let host = "";
            let rawPath = "";
            try {
              const parsed = new URL(rawUrl);
              host = parsed.host;
              rawPath = parsed.pathname;
            } catch { /* fall through to track('') */ }
            track(AhaEvent.AppOpenedFromDeepLink, { host, path: rawPath });

            // A `helpr://` URL means Stripe just handed us back from the
            // in-app browser sheet. Close it first — otherwise we route
            // underneath a sheet that is still covering the screen and the
            // user sees nothing change.
            if (rawUrl.startsWith(`${NATIVE_RETURN_SCHEME}:`)) {
              try {
                await Browser.close();
              } catch (err) {
                // Already dismissed, or no sheet open. Routing is what
                // matters; never let this stop the hand-back.
                report(err, { tags: { source: "nativeReturn.browserClose" } });
              }
            }

            const internal = normalizeDeepLinkUrl(rawUrl);
            if (internal) {
              // Mark first so NativeLaunchRouter (which may resolve a
              // moment later in a parallel useEffect) doesn't override
              // the deep link with the default post-auth route.
              claimDeepLinkLaunch();
              navigate(internal);
            }
          } catch (err) {
            report(err, { tags: { source: "appUrlOpen" }, context: { url: rawUrl } });
          }
        };

        await App.addListener("appUrlOpen", (event) => {
          // Listener signature is sync; the handler awaits Browser.close(), so
          // surface any rejection rather than letting it become an unhandled one.
          void handleIncomingUrl(event.url).catch((err) =>
            report(err, { tags: { source: "appUrlOpen" } }),
          );
        });

        // Cold-launch: if the app was opened FROM a Universal Link
        // (rather than the home-screen icon), `appUrlOpen` may have
        // already fired before this listener was attached, or — on
        // some iOS versions — not fired at all. Querying
        // App.getLaunchUrl() on every boot is cheap and idempotent;
        // resolveNativeLaunchRoute won't override us because it only
        // intervenes when currentPath === "/" AND no navigate() has
        // happened yet.
        try {
          const launch = await App.getLaunchUrl();
          if (launch?.url) await handleIncomingUrl(launch.url);
        } catch (err) {
          report(err, { tags: { source: "getLaunchUrl" } });
        }
      } catch (err) {
        report(err, { tags: { source: "useNativePushSetup" } });
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [navigate]);
}

/**
 * Trigger the OS-level permission prompt directly. Prefer
 * `requestPushPermissionWithRationale` from a React component so the user
 * sees a friendly pre-prompt first (Apple App Review requires this).
 */
export async function requestPushPermission(): Promise<boolean> {
  if (!isNativePlatform) return false;

  // HARD GATE — never raise the OS prompt for a signed-out user.
  //
  // iOS gives an app exactly ONE chance at this prompt for the lifetime of the
  // install. Once it is dismissed with "Don't Allow" the OS silently no-ops
  // every later requestPermissions() call, and the only recovery is the user
  // manually finding the app in Settings. So the prompt must be spent at a
  // moment the user has a reason to say yes.
  //
  // A guest has no such reason and, more concretely, CANNOT receive push at
  // all: savePushToken writes a push_tokens row keyed on user_id, so a token
  // obtained while signed out is discarded. Prompting them can only ever burn
  // the one shot for zero benefit.
  //
  // Observed on an iOS 26.1 sim during the 2026-08-08 audit: a cold launch as a
  // guest surfaced the native prompt over the Browse-jobs screen with no
  // preceding rationale dialog — i.e. something reached this function outside
  // the intended useRequestPushPermission → rationale flow. Rather than rely on
  // every present and future call site being disciplined, the chokepoint itself
  // now refuses. The deliberate flows are unaffected: NotificationPanel's
  // "Enable" tap and the high-intent nudges all run for signed-in users.
  try {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) {
      track("permission_skipped_guest", { kind: "push" });
      return false;
    }
  } catch (sessionErr) {
    // Fail CLOSED: if we cannot prove someone is signed in, do not spend the
    // one-shot prompt on them.
    report(sessionErr, { tags: { source: "requestPushPermission.sessionCheck" } });
    return false;
  }

  try {
    const { PushNotifications } = await import("@capacitor/push-notifications");
    const status = await PushNotifications.requestPermissions();
    // Keep the synchronous accessor in step with the answer the user just
    // gave — otherwise NotificationPanel keeps showing "Turn on
    // notifications" until the next cold launch re-primes the cache.
    publishNativePermission(status.receive);
    if (status.receive === "granted") {
      await PushNotifications.register();
      return true;
    }
    track("permission_denied", { kind: "push" });
    return false;
  } catch (err) {
    report(err, { tags: { source: "requestPushPermission" } });
    return false;
  }
}

/**
 * Hook-friendly variant: shows the in-app rationale dialog FIRST, then
 * (on confirm) triggers the OS-level permission prompt.
 *
 * Works on both native (Capacitor PushNotifications.requestPermissions)
 * and web (Notification.requestPermission, after registering /sw-push.js).
 * Using the same hook for both keeps the rationale UX consistent, which
 * is also what App Review looks for on the native side.
 *
 * Returns false on platforms that don't support notifications at all
 * (e.g. SSR or a browser without the Notification API).
 */
export function useRequestPushPermission() {
  const { request } = usePermissionRationale();
  return async (): Promise<boolean> => {
    if (isNativePlatform) {
      let granted = false;
      await request("notifications", async () => {
        granted = await requestPushPermission();
      });
      return granted;
    }
    if (!isPushSupported()) return false;
    let granted = false;
    await request("notifications", async () => {
      await registerServiceWorker();
      granted = await requestWebPushPermission();
    });
    return granted;
  };
}

/**
 * Remove this device's push token for the signing-out user. Call on sign-out.
 *
 * Deletes by (user_id, token) when this session saw the device token, so
 * signing out here doesn't kill push on the user's other devices. On NATIVE,
 * when the token is unknown (registration never fired this session), it falls
 * back to the user-wide delete — the handed-off-device privacy leak
 * (F-PRIV-01) is worse than a re-registration on the next sign-in. On WEB the
 * fallback is skipped entirely; see the comment in the body.
 *
 * Best-effort — a failure never blocks logout — but it must NOT be silent:
 * a swallowed delete failure leaves the token behind and re-opens F-PRIV-01
 * with no trace. Surface both a returned Supabase `error` and any thrown
 * exception to monitoring, then let sign-out proceed regardless.
 */
export async function unregisterPushOnSignOut(userId: string) {
  try {
    // WEB SIGN-OUT MUST NEVER TOUCH NATIVE TOKENS.
    //
    // `push_tokens` only ever holds rows written by the native registration
    // listener (platform 'ios' | 'android') — web push does not persist a
    // row here at all. So on web, `currentDeviceToken` is always null and the
    // user-wide fallback below would delete the user's PHONE tokens because
    // they signed out of a browser tab. That is all cost and no benefit: it
    // protects nothing on the device being signed out of (there is nothing
    // there to protect) and silently kills push on a device the user still
    // holds. The hand-off leak F-PRIV-01 the fallback exists for is a
    // shared-DEVICE concern, so scope the fallback to native.
    if (!isNativePlatform && !currentDeviceToken) return;

    let query = supabase.from("push_tokens").delete().eq("user_id", userId);
    if (currentDeviceToken) query = query.eq("token", currentDeviceToken);
    // No unwrapMutation row-count guard: zero rows deleted is a legitimate
    // and common outcome here (the user never granted push, or already
    // signed out on this device), so an empty result is not a silent failure.
    const { error } = await query;
    if (error) {
      report(error, {
        severity: "warning",
        tags: { area: "push", op: "unregisterOnSignOut" },
      });
    }
  } catch (err) {
    report(err, {
      severity: "warning",
      tags: { area: "push", op: "unregisterOnSignOut" },
    });
  }
}
